// Responsibility: Dynamically mutate game rules by hijacking physics and chaos systems to create a living, unpredictable game state. // Attachment Note: Attach this to an empty GameObject in the scene to act as the master controller of reality shifts. using UnityEngine; public class EntropyEngine : MonoBehaviour { private void Update() { if (Random.value < 0.001f) TriggerRealityShift(); } public void TriggerRealityShift() { Debug.Log("Reality is fracturing..."); GlobalPhysicsManager.Instance?.SetGravityMultiplier(Random.Range(-2f, 2f)); Time.timeScale = Random.Range(0.5f, 2.0f); ChaosModeManager.Instance?.ApplyRandomForce(); } }